import{_ as a,o as e,c as l,ae as i}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"第1周：数据觉醒","description":"","frontmatter":{"title":"第1周：数据觉醒"},"headers":[],"relativePath":"week01/index.md","filePath":"week01/index.md"}'),d={name:"week01/index.md"};function r(h,t,o,p,n,c){return e(),l("div",null,[...t[0]||(t[0]=[i('<p><strong>第1讲</strong></p><p><strong>数据觉醒</strong></p><p><em>“你的每一次点击，都在被记录”</em></p><p>客户数据分析技术</p><p>阶段一：数据基础与客户认知</p><table tabindex="0"><thead><tr><th>64学时 | 4学分 | 核心工具：Excel + Kimi/ChatGPT + Power BI</th></tr></thead></table><h1 id="一、情景导入-小林的第一天" tabindex="-1">一、情景导入：小林的第一天 <a class="header-anchor" href="#一、情景导入-小林的第一天" aria-label="Permalink to &quot;一、情景导入：小林的第一天&quot;">​</a></h1><p>小林是「潮玩星球」电商公司新入职的运营助理，今天是她上班第一天。老板王总把她叫到办公室，递给她一个U盘说：“这是咱们过去一年的客户订单数据，10万行，你先看看能发现什么。”小林打开Excel，看到密密麻麻的数字，脑子里只有一个想法：“这些数字跟我有什么关系？”</p><p>王总接着说：“对了，隔壁组的小张，上周用AI工具分析了同样的数据，发现了一个我们做了三年都没注意到的客户群体，帮公司多赚了50万。你好好学学。”</p><p><strong>小林突然意识到：在这个AI时代，不会看数据的人，可能真的要被淘汰了。</strong></p><h1 id="二、知识讲解" tabindex="-1">二、知识讲解 <a class="header-anchor" href="#二、知识讲解" aria-label="Permalink to &quot;二、知识讲解&quot;">​</a></h1><h3 id="_2-1-什么是客户数据" tabindex="-1">2.1 什么是客户数据？ <a class="header-anchor" href="#_2-1-什么是客户数据" aria-label="Permalink to &quot;2.1 什么是客户数据？&quot;">​</a></h3><p>客户数据，是企业在与客户互动过程中产生的所有信息的总和。它不仅仅是一个Excel表格，而是客户与品牌之间关系的“数字化影像”。我们可以将客户数据分为三大类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>定义</th><th>举例</th><th>获取方式</th></tr></thead><tbody><tr><td>交易数据</td><td>客户购买行为的直接记录</td><td>订单金额、购买频次、退货记录</td><td>电商后台、POS系统</td></tr><tr><td>行为数据</td><td>客户与品牌互动的行为轨迹</td><td>浏览记录、搜索关键词、页面停留时间</td><td>网站埋点、APP分析</td></tr><tr><td>画像数据</td><td>客户自身的属性信息</td><td>年龄、性别、地区、会员等级</td><td>注册信息、问卷调查</td></tr></tbody></table><p>**关键洞察：**<em>交易数据告诉你“客户买了什么”，行为数据告诉你“客户想买什么”，画像数据告诉你“客户是谁”。三者结合，才能画出完整的客户画像。</em></p><h3 id="_2-2-数据在商业中的价值" tabindex="-1">2.2 数据在商业中的价值 <a class="header-anchor" href="#_2-2-数据在商业中的价值" aria-label="Permalink to &quot;2.2 数据在商业中的价值&quot;">​</a></h3><p>让我们看几个真实的商业案例，感受数据的巨大威力：</p><ul><li><p>阿里巴巴万相台无界版：AI圈人工具使商家平均转化效率提升32%，通过智能匹配将合适的产品推送给合适的人，大幅降低了广告浪费</p></li><li><p>抖音电商：2025年GMV达4.3万亿元，背后是数据驱动的推荐系统——每一个“列表滑动”都是数据算法在起作用</p></li><li><p>某生鲜电商：通过动态定价（根据库存、天气、用户行为自动调整价格）将利润率提升8%-12%**核心观点：**<em>数据不是数字，而是“客户的 voice”——客户通过每一次点击、每一次购买在“说话”。你的工作，就是学会“听”懂这些声音。</em></p></li></ul><h3 id="_2-3-ai时代的数据分析师" tabindex="-1">2.3 AI时代的数据分析师 <a class="header-anchor" href="#_2-3-ai时代的数据分析师" aria-label="Permalink to &quot;2.3 AI时代的数据分析师&quot;">​</a></h3><p>传统的数据分析师和AI时代的数据分析师有着本质的区别。让我们通过一张表格来对比：</p><table tabindex="0"><thead><tr><th>维度</th><th>传统分析师</th><th>AI时代分析师</th></tr></thead><tbody><tr><td>核心工作</td><td>写SQL、做报表</td><td>提出问题、验证结论</td></tr><tr><td>工具</td><td>手动操作Excel/SPSS</td><td>人机协作（AI辅助）</td></tr><tr><td>价值</td><td>数据搬运</td><td>商业洞察</td></tr></tbody></table><p>权威数据支撑了这一趋势：</p><ul><li><p>Gartner预测：到2028年，75%的新分析内容由GenAI处理，传统的手动报表制作将大幅减少</p></li><li><p>World Economic Forum将“分析思维”列为2025年全球最重要的核心技能之一，超越了编程和统计学**本课程的定位：**培养“分析指挥官”——你负责提问和判断，AI负责执行。这个课程不是教你写代码，而是教你如何像一个“指挥官”一样，指挥AI工具为你服务，从数据中发现商业机会。</p></li></ul><h1 id="三、操作步骤-认识你的数据" tabindex="-1">三、操作步骤：认识你的数据 <a class="header-anchor" href="#三、操作步骤-认识你的数据" aria-label="Permalink to &quot;三、操作步骤：认识你的数据&quot;">​</a></h1><p>**任务：**打开「潮玩星球」客户数据集（Excel），完成以下操作。</p><h3 id="步骤1-观察数据全貌" tabindex="-1">步骤1：观察数据全貌 <a class="header-anchor" href="#步骤1-观察数据全貌" aria-label="Permalink to &quot;步骤1：观察数据全貌&quot;">​</a></h3><ul><li><p>打开Excel文件，查看有多少行、多少列</p></li><li><p>滚动浏览前20行，感受数据的“样子”</p></li><li><p>思考：这些列分别属于什么数据类型？</p></li></ul><h3 id="步骤2-用ai辅助理解数据" tabindex="-1">步骤2：用AI辅助理解数据 <a class="header-anchor" href="#步骤2-用ai辅助理解数据" aria-label="Permalink to &quot;步骤2：用AI辅助理解数据&quot;">​</a></h3><ul><li><p>打开Kimi（kimi.moonshot.cn），上传Excel文件</p></li><li><p>输入Prompt：“请帮我分析这个数据集，告诉我：1.有多少行多少列 2.每列的数据类型是什么 3.有没有明显的数据问题”</p></li><li><p>观察AI的分析结果，思考：AI的理解和你的一样吗？有什么遗漏？</p></li></ul><h3 id="步骤3-记录你的发现" tabindex="-1">步骤3：记录你的发现 <a class="header-anchor" href="#步骤3-记录你的发现" aria-label="Permalink to &quot;步骤3：记录你的发现&quot;">​</a></h3><p>在笔记本上回答以下问题：</p><ul><li><p>这个数据集记录了什么业务？</p></li><li><p>哪些列是交易数据？哪些是行为数据？哪些是画像数据？</p></li><li><p>你觉得这个数据集能回答什么商业问题？</p></li></ul><h1 id="四、课堂练习" tabindex="-1">四、课堂练习 <a class="header-anchor" href="#四、课堂练习" aria-label="Permalink to &quot;四、课堂练习&quot;">​</a></h1><h3 id="练习1-数据类型识别-基础" tabindex="-1">练习1：数据类型识别（基础） <a class="header-anchor" href="#练习1-数据类型识别-基础" aria-label="Permalink to &quot;练习1：数据类型识别（基础）&quot;">​</a></h3><p>以下是5个数据字段的描述，请判断它们分别属于哪种类型（交易数据/行为数据/画像数据）：</p><ul><li><p>客户最近一次购买距今天的天数 → ?</p></li><li><p>客户在过去30天内浏览了多少个商品页面 → ?</p></li><li><p>客户的性别和年龄 → ?</p></li><li><p>客户累计消费总金额 → ?</p></li><li><p>客户是否使用了优惠券 → ?</p></li></ul><h3 id="练习2-商业问题转化-进阶" tabindex="-1">练习2：商业问题转化（进阶） <a class="header-anchor" href="#练习2-商业问题转化-进阶" aria-label="Permalink to &quot;练习2：商业问题转化（进阶）&quot;">​</a></h3><p>以下是3个商业问题，请思考需要什么数据来回答：</p><ul><li><p>“哪些客户最有可能在下个月流失？” → 需要什么数据？</p></li><li><p>“我们应该给哪些客户发优惠券？” → 需要什么数据？</p></li><li><p>“我们的核心客户群体有什么特征？” → 需要什么数据？</p></li></ul><h1 id="五、课后任务" tabindex="-1">五、课后任务 <a class="header-anchor" href="#五、课后任务" aria-label="Permalink to &quot;五、课后任务&quot;">​</a></h1><ul><li><p>项目任务P1-1：完成「潮玩星球」客户数据集的数据字典（模板已提供）</p></li><li><p>思考题：在日常生活中，你遇到过哪些“数据分析”的场景？（比如淘宝推荐、抖音信息流、外卖满减等）</p></li><li><p>AI工具探索：注册Kimi账号，尝试上传一个CSV文件，观察AI能做什么</p></li></ul><hr><h2 id="📊-本课数据" tabindex="-1">📊 本课数据 <a class="header-anchor" href="#📊-本课数据" aria-label="Permalink to &quot;📊 本课数据&quot;">​</a></h2><p>本课练习可使用以下数据集：</p><table tabindex="0"><thead><tr><th>数据集</th><th>说明</th><th>下载</th></tr></thead><tbody><tr><td><a href="/data/customer_data.csv">客户主数据</a></td><td>客户主数据，用于认识数据类型</td><td><a href="/data/customer_data.csv">下载</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">使用建议</p><p>下载 CSV 文件后，可导入 Kimi/ChatGPT 进行 AI 辅助分析，或用 Excel/Power BI 进行可视化。</p></div>',46)])])}const b=a(d,[["render",r]]);export{u as __pageData,b as default};
